import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    strings = data[1:1 + n]

    seen = set()
    pref = set()
    suff = set()

    for s in strings:
        invalid = False

        if s in seen:
            invalid = True
        else:
            for x in range(1, 10):
                if s[:x] in suff and s[x:] in pref:
                    invalid = True
                    break

        if invalid:
            sys.stdout.write(s + "\n")
            return

        seen.add(s)

        for l in range(1, 10):
            pref.add(s[:l])
            suff.add(s[10 - l:])

    sys.stdout.write("ok\n")

if __name__ == "__main__":
    main()
